#include <bits/stdc++.h>
using namespace std;

const int N = 18;
const uint8_t UNREACHABLE = 255;

int n, R, B;
int r[N], b[N], a[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c >> r[i] >> b[i];
        R += r[i];
        B += b[i];
        a[i] = (c == 'B');
    }

    const int states = 1 << n;
    const int width = n * n;

    vector<array<uint8_t, 2>> cnt(states);
    for (int mask = 1; mask < states; ++mask) {
        int bit = __builtin_ctz(mask);
        int previous = mask ^ (1 << bit);
        cnt[mask] = cnt[previous];
        ++cnt[mask][a[bit]];
    }

    vector<uint8_t> dp(static_cast<size_t>(states) * width, UNREACHABLE);
    dp[0] = 0;

    for (int mask = 1; mask < states; ++mask) {
        uint8_t* current = dp.data() + static_cast<size_t>(mask) * width;

        for (int j = 0; j < width; ++j) {
            for (int k = 0; k < n; ++k) {
                if (!(mask & (1 << k))) continue;

                int previousMask = mask ^ (1 << k);
                int previousRed = max(j - min(r[k], static_cast<int>(cnt[previousMask][0])), 0);
                uint8_t previousValue =
                    dp[static_cast<size_t>(previousMask) * width + previousRed];

                if (previousValue == UNREACHABLE) continue;

                int candidate =
                    previousValue + min(b[k], static_cast<int>(cnt[previousMask][1]));

                if (current[j] == UNREACHABLE || candidate > current[j])
                    current[j] = static_cast<uint8_t>(candidate);
            }
        }
    }

    int answer = INT_MAX;
    int all = states - 1;
    const uint8_t* finalState = dp.data() + static_cast<size_t>(all) * width;

    for (int i = 0; i < width; ++i) {
        if (finalState[i] != UNREACHABLE)
            answer = min(answer, max(R - i, B - static_cast<int>(finalState[i])));
    }

    cout << answer + n << '\n';
    return 0;
}

