int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, R = 0, B = 0;
    cin >> n;

    vector<int> r(n), b(n), color(n);
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c >> r[i] >> b[i];
        R += r[i];
        B += b[i];
        color[i] = (c == 'B');
    }

    const int states = 1 << n;
    const int width = n * n;
    const int16_t NEG = -30000;

    vector<array<unsigned char, 2>> cnt(states);
    vector<int16_t> dp(static_cast<size_t>(states) * width, NEG);
    dp[0] = 0;

    for (int mask = 1; mask < states; ++mask) {
        int bit = __builtin_ctz(mask);
        int previous = mask ^ (1 << bit);
        cnt[mask] = cnt[previous];
        ++cnt[mask][color[bit]];

        size_t base = static_cast<size_t>(mask) * width;

        for (int j = 0; j < width; ++j) {
            int best = NEG;

            for (int k = 0; k < n; ++k) {
                if (mask & (1 << k)) {
                    int next = mask ^ (1 << k);
                    int previousRed = max(j - min(r[k], static_cast<int>(cnt[next][0])), 0);
                    int value = dp[static_cast<size_t>(next) * width + previousRed];

                    if (value != NEG) {
                        value += min(b[k], static_cast<int>(cnt[next][1]));
                        best = max(best, value);
                    }
                }
            }

            dp[base + j] = static_cast<int16_t>(best);
        }
    }

    int answer = INT_MAX;
    int all = states - 1;
    size_t base = static_cast<size_t>(all) * width;

    for (int i = 0; i < width; ++i) {
        int blue = dp[base + i];
        if (blue >= 0)
            answer = min(answer, max(R - i, B - blue));
    }

    cout << answer + n << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> r(n), b(n);
    int R = 0, B = 0, redMask = 0;

    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c >> r[i] >> b[i];
        R += r[i];
        B += b[i];
        if (c == 'R') redMask |= 1 << i;
    }

    const int states = 1 << n;
    const int width = n * (n - 1) / 2 + 1;
    const uint8_t INF = 255;

    vector<uint8_t> redCount(states), blueCount(states);
    for (int mask = 1; mask < states; ++mask) {
        int bit = __builtin_ctz(mask);
        int previous = mask & (mask - 1);
        redCount[mask] = redCount[previous] + ((redMask >> bit) & 1);
        blueCount[mask] = blueCount[previous] + !((redMask >> bit) & 1);
    }

    vector<uint8_t> dp(static_cast<size_t>(states) * width, INF);
    dp[0] = 0;

    for (int mask = 1; mask < states; ++mask) {
        uint8_t* current = &dp[static_cast<size_t>(mask) * width];

        for (int k = 0; k < n; ++k) {
            if (!(mask & (1 << k))) continue;

            int previousMask = mask ^ (1 << k);
            const uint8_t* previous =
                &dp[static_cast<size_t>(previousMask) * width];

            int redGain = min(r[k], static_cast<int>(redCount[previousMask]));
            int blueGain = min(b[k], static_cast<int>(blueCount[previousMask]));

            for (int savedRed = 0; savedRed < width; ++savedRed) {
                int previousRed = max(savedRed - redGain, 0);
                if (previous[previousRed] == INF) continue;

                uint8_t candidate =
                    static_cast<uint8_t>(previous[previousRed] + blueGain);

                if (current[savedRed] == INF ||
                    candidate > current[savedRed]) {
                    current[savedRed] = candidate;
                }
            }
        }
    }

    int answer = INT_MAX;
    const uint8_t* result =
        &dp[static_cast<size_t>(states - 1) * width];

    for (int savedRed = 0; savedRed < width; ++savedRed) {
        if (result[savedRed] != INF) {
            answer = min(answer,
                         max(R - savedRed,
                             B - static_cast<int>(result[savedRed])));
        }
    }

    cout << answer + n << '\n';
    return 0;
}

