    int n;
    cin >> n;

    vector<int> r(n), b(n), color(n);
    long long R = 0, B = 0;

    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c >> r[i] >> b[i];
        color[i] = (c == 'B');
        R += r[i];
        B += b[i];
    }

    const int states = 1 << n;
    const int width = n * n;
    const int16_t NEG = -30000;

    vector<uint8_t> redCount(states), blueCount(states);
    for (int mask = 1; mask < states; ++mask) {
        int bit = __builtin_ctz(mask);
        int previous = mask & (mask - 1);
        redCount[mask] = redCount[previous] + (color[bit] == 0);
        blueCount[mask] = blueCount[previous] + (color[bit] == 1);
    }

    vector<int16_t> dp(static_cast<size_t>(states) * width, NEG);
    dp[0] = 0;

    for (int mask = 1; mask < states; ++mask) {
        size_t currentBase = static_cast<size_t>(mask) * width;

        for (int savedRed = 0; savedRed < width; ++savedRed) {
            int best = NEG;

            for (int k = 0; k < n; ++k) {
                if (!(mask & (1 << k))) continue;

                int previous = mask ^ (1 << k);
                int redBonus = min(r[k], static_cast<int>(redCount[previous]));
                int blueBonus = min(b[k], static_cast<int>(blueCount[previous]));
                int previousRed = max(savedRed - redBonus, 0);

                int value = dp[static_cast<size_t>(previous) * width + previousRed];
                if (value != NEG)
                    best = max(best, value + blueBonus);
            }

            dp[currentBase + savedRed] = static_cast<int16_t>(best);
        }
    }

    int all = states - 1;
    long long answer = LLONG_MAX;
    size_t finalBase = static_cast<size_t>(all) * width;

    for (int savedRed = 0; savedRed < width; ++savedRed) {
        int savedBlue = dp[finalBase + savedRed];
        if (savedBlue >= 0)
            answer = min(answer, max(R - savedRed, B - savedBlue));
    }

    cout << answer + n << '\n';
    return 0;
}

