    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, R = 0, B = 0;
    cin >> n;

    vector<int> r(n), b(n), color(n);
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c >> r[i] >> b[i];
        R += r[i];
        B += b[i];
        color[i] = (c == 'B');
    }

    const int states = 1 << n;
    const int width = n * n;
    const int16_t NEG = -30000;

    vector<array<uint8_t, 2>> cnt(states);
    for (int mask = 1; mask < states; ++mask) {
        int bit = __builtin_ctz(mask);
        int previous = mask ^ (1 << bit);
        cnt[mask] = cnt[previous];
        ++cnt[mask][color[bit]];
    }

    vector<int16_t> dp(static_cast<size_t>(states) * width, NEG);
    dp[0] = 0;

    for (int mask = 1; mask < states; ++mask) {
        int16_t* current = dp.data() + static_cast<size_t>(mask) * width;

        for (int bits = mask; bits; bits &= bits - 1) {
            int k = __builtin_ctz(bits);
            int previousMask = mask ^ (1 << k);
