        dp.data() + static_cast<size_t>(states - 1) * width;

    for (int savedRed = 0; savedRed < width; ++savedRed) {
        if (finalState[savedRed] >= 0) {
            answer = min(answer, max(R - savedRed, B - finalState[savedRed]));
        }
    }

    cout << answer + n << '\n';
    return 0;
